#include <stdio.h>
#include <math.h>

int main(void){
    const int W=2400,H=1800;
    FILE*f=fopen("reconstructed.ppm","w");
    fprintf(f,"P3\n%d %d\n255\n",W,H);
    float a=(float)W/(float)H, T=1.0f;
    float Cx=0.0f,Cy=0.663f,Cz=-3.243f,R=0.663f,S=2.0f/3.0f;
    float Lx=0.60f,Ly=0.59f,Lz=-0.54f;
    float ln=sqrtf(Lx*Lx+Ly*Ly+Lz*Lz); Lx/=ln; Ly/=ln; Lz/=ln;
    for(int py=0;py<H;py++){
        float v=1.0f-((float)py+0.5f)/(float)H*2.0f;
        for(int px=0;px<W;px++){
            float u=((float)px+0.5f)/(float)W*2.0f-1.0f;
            float dx=u*a*T, dy=v*T, dz=-1.0f;
            float n=sqrtf(dx*dx+dy*dy+dz*dz); dx/=n; dy/=n; dz/=n;
            float r,g,b;
            /* sky */
            r=191.0f-63.66f*dy; g=217.0f-38.2f*dy; b=255.0f;
            /* floor plane y=0 */
            if(dy<-1e-6f){
                float t=1.0f/(-dy);
                float Px=t*dx, Pz=t*dz;
                long cx=(long)floorf(Px/S), cz=(long)floorf(Pz/S);
                float col=(((cx+cz)&1L)==0)?152.0f:67.0f;
                float ox=Px-Cx, oy=-Cy, oz=Pz-Cz;
                float bb=2.0f*(ox*Lx+oy*Ly+oz*Lz);
                float cc=ox*ox+oy*oy+oz*oz-R*R;
                float disc=bb*bb-4.0f*cc;
                if(disc>0.0f){
                    float tt=(-bb-sqrtf(disc))*0.5f;
                    if(tt>0.0f) col*=0.30f;
                }
                r=g=b=col;
            }
            /* sphere */
            float ocx=-Cx, ocy=1.0f-Cy, ocz=-Cz;
            float bb=2.0f*(dx*ocx+dy*ocy+dz*ocz);
            float cc=ocx*ocx+ocy*ocy+ocz*ocz-R*R;
            float d2=bb*bb-4.0f*cc;
            if(d2>0.0f){
                float ts=(-bb-sqrtf(d2))*0.5f;
                if(ts>0.0f){
                    float sx=ts*dx, sy=ts*dy+1.0f, sz=ts*dz;
                    float nx=(sx-Cx)/R, ny=(sy-Cy)/R, nz=(sz-Cz)/R;
                    float ndl=nx*Lx+ny*Ly+nz*Lz; if(ndl<0.0f) ndl=0.0f;
                    r=51.0f+207.0f*ndl; g=b=10.0f+40.0f*ndl;
                }
            }
            int ri=(int)(r+0.5f), gi=(int)(g+0.5f), bi=(int)(b+0.5f);
            if(ri>255)ri=255; if(gi>255)gi=255; if(bi>255)bi=255;
            if(ri<0)ri=0; if(gi<0)gi=0; if(bi<0)bi=0;
            fprintf(f,"%d %d %d\n",ri,gi,bi);
        }
    }
    fclose(f);
    return 0;
}
